/** Q13-test-local interpreter of the published spreadsheet subset. Never used
 * by generators or the app. No eval/Function or production solver imports. */
import assert from'node:assert/strict';
export type Cell=number|string|null;export type Sheet=Map<string,Cell>;export type Book={来店状況:Sheet;分析:Sheet};
type Ref={kind:'ref';sheet?:string;col:string;row:number;absolute:boolean;endCol?:string;endRow?:number;endAbsolute?:boolean};
type Node=Ref|{kind:'literal';value:Cell}|{kind:'op';op:string;left:Node;right:Node}|{kind:'criterion';op:string;value:Node}|{kind:'fn';name:string;args:Node[]};
type Value=Cell|Cell[][]|{op:string;value:Cell};
export function parseFormula(text:string):Node{const normalized=text.replaceAll('−','-').replaceAll('≤','<=').replaceAll('≥','>='),tokens:string[]=[];let p=0;const re=/\s+|(?:来店状況!)?\$?[A-J]\$?\d+(?::\$?[A-J]\$?\d+)?|条件付個数|条件付合計|切捨て|照合検索|照合一致|垂直照合|表引き|順位|合計|平均|IF|null|\d+(?:\.\d+)?|<=|>=|[()+*/=<>,-]/y;while(p<normalized.length){re.lastIndex=p;const m=re.exec(normalized);if(!m)throw Error('UNPARSED '+normalized.slice(p));p=re.lastIndex;if(m[0].trim())tokens.push(m[0]);}let i=0;const take=(s:string)=>{assert.equal(tokens[i++],s);};
 const atom=():Node=>{const t=tokens[i++];if(t==='('){const n=expression();take(')');return n;}if(t==='null')return{kind:'literal',value:null};if(/^\d/.test(t))return{kind:'literal',value:Number(t)};const cell=/^(?:(来店状況)!)?\$?([A-J])(\$?)(\d+)(?::\$?([A-J])(\$?)(\d+))?$/.exec(t);if(cell)return{kind:'ref',sheet:cell[1],col:cell[2],row:Number(cell[4]),absolute:cell[3]==='$',endCol:cell[5],endRow:cell[7]?Number(cell[7]):undefined,endAbsolute:cell[6]==='$'};take('(');const args:Node[]=[];do{if(['<','>','=','<=','>='].includes(tokens[i]))args.push({kind:'criterion',op:tokens[i++],value:expression()});else args.push(expression());if(tokens[i]!==',')break;i++;}while(true);take(')');return{kind:'fn',name:t,args};};
 const product=():Node=>{let n=atom();while(['*','/'].includes(tokens[i]))n={kind:'op',left:n,op:tokens[i++],right:atom()};return n;};const sum=():Node=>{let n=product();while(['+','-'].includes(tokens[i]))n={kind:'op',left:n,op:tokens[i++],right:product()};return n;};const expression=():Node=>{let n=sum();if(['<','>','=','<=','>='].includes(tokens[i]))n={kind:'op',left:n,op:tokens[i++],right:sum()};return n;};const n=expression();assert.equal(i,tokens.length);return n;}
function scalar(v:Value):Cell{if(Array.isArray(v)||typeof v==='object'&&v!==null)throw Error('NOT_SCALAR');return v;}
function number(v:Value){const n=scalar(v);if(typeof n!=='number'||!Number.isFinite(n))throw Error('NOT_NUMERIC');return n;}
const comparison=(a:Cell,op:string,b:Cell)=>op==='='?a===b:op==='>'?a!==null&&b!==null&&a>b:op==='<'?a!==null&&b!==null&&a<b:op==='>='?a!==null&&b!==null&&a>=b:a!==null&&b!==null&&a<=b;
function range(v:Value){if(!Array.isArray(v))throw Error('NOT_RANGE');return v;}
export function evaluate(n:Node,book:Book,sheet:keyof Book,offset=0):Value{const ev=(x:Node)=>evaluate(x,book,sheet,offset);if(n.kind==='literal')return n.value;if(n.kind==='ref'){const s=book[(n.sheet??sheet)as keyof Book],r=n.row+(n.absolute?0:offset);if(!n.endCol)return s.get(n.col+r)??null;const end=n.endRow!+(n.endAbsolute?0:offset),cells:Cell[][]=[];for(let row=r;row<=end;row++){const line:Cell[]=[];for(let col=n.col.charCodeAt(0);col<=n.endCol.charCodeAt(0);col++)line.push(s.get(String.fromCharCode(col)+row)??null);cells.push(line);}return cells;}
 if(n.kind==='criterion')return{op:n.op,value:scalar(ev(n.value))};if(n.kind==='op'){const l=ev(n.left),r=ev(n.right);if(['=','<','>','<=','>='].includes(n.op))return comparison(scalar(l),n.op,scalar(r))?1:0;const a=number(l),b=number(r);if(n.op==='+')return a+b;if(n.op==='-')return a-b;if(n.op==='*')return a*b;if(b===0)throw Error('DIV0');return a/b;}
 if(n.name==='IF')return number(ev(n.args[0]))?ev(n.args[1]):ev(n.args[2]);const args=n.args.map(ev),nums=(v:Value)=>range(v).flat().filter((x):x is number=>typeof x==='number');
 switch(n.name){case'合計':return nums(args[0]).reduce((a,b)=>a+b,0);case'平均':{const a=nums(args[0]);if(!a.length)throw Error('EMPTY_AVERAGE');return a.reduce((a,b)=>a+b,0)/a.length;}case'条件付個数':{const c=args[1];if(!c||Array.isArray(c)||typeof c!=='object')throw Error('CRITERION');return range(args[0]).flat().filter(x=>x!==null&&comparison(x,c.op,c.value)).length;}case'条件付合計':{const c=args[1];if(!c||Array.isArray(c)||typeof c!=='object')throw Error('CRITERION');const test=range(args[0]).flat(),values=range(args[2]).flat();assert.equal(test.length,values.length);return test.reduce<number>((sum,x,i)=>x!==null&&comparison(x,c.op,c.value)&&typeof values[i]==='number'?sum+(values[i]as number):sum,0);}case'切捨て':{const factor=10**number(args[1]);return Math.trunc(number(args[0])*factor)/factor;}case'順位':{const x=number(args[0]),desc=number(args[2])===1;return 1+nums(args[1]).filter(y=>desc?y>x:y<x).length;}case'照合検索':{const find=range(args[1]).flat(),ret=range(args[2]).flat();const i=find.findIndex(x=>x===scalar(args[0]));if(i<0)throw Error('NOT_FOUND');return ret[i];}case'照合一致':{assert.equal(number(args[2]),0);const i=range(args[1]).flat().findIndex(x=>x===scalar(args[0]));if(i<0)throw Error('NOT_FOUND');return i+1;}case'表引き':{const a=range(args[0]),r=number(args[1]),c=number(args[2]);if(!Number.isInteger(r)||!Number.isInteger(c)||r<1||r>a.length||c<1||c>a[0].length)throw Error('RANGE');return a[r-1][c-1];}case'垂直照合':{assert.equal(number(args[3]),0);const row=range(args[1]).find(r=>r[0]===scalar(args[0]));const c=number(args[2]);if(!row||c<1||c>row.length)throw Error('NOT_FOUND');return row[c-1];}default:throw Error(n.name);}}
export type Visit={number:number;receipt:number;service:string;duration:number;window:number;start:number;end:number;wait:number;waiting:number;rank:number};
/** Independent queue: sort all available-window events per visit, pop/push. */
export function queue(receipts:{number:number;receipt:number;service:string;duration:number}[],windows:number):Visit[]{let events=Array.from({length:windows},(_,i)=>({at:0,window:i+1}));const result:Visit[]=[];for(const r of receipts){events.sort((a,b)=>a.at-b.at||a.window-b.window);const event=events.shift()!,start=r.receipt>event.at?r.receipt:event.at;result.push({...r,window:event.window,start,end:start+r.duration,wait:start-r.receipt,waiting:result.filter(p=>p.start>r.receipt&&p.wait!==0).length,rank:0});events.push({at:start+r.duration,window:event.window});}const ranked=[...result].sort((a,b)=>b.wait-a.wait||a.number-b.number);for(const row of result)row.rank=ranked.indexOf(row)+1;return result;}
export function independentCase(v:number[]):Visit[]{assert.equal(v.length,1);assert(v[0]>=1&&v[0]<=1080);const id=v[0]-1,e=id%6,d=Math.floor(id/6)%4,c=Math.floor(id/24)%3,b=Math.floor(id/72)%3,a=Math.floor(id/216),t=600+a*15,u=b+1,firstDuration=3*u+[5,10,15][c]*u,n=[12,18,24,36][d],cycle=['ABC','ACB','BAC','BCA','CAB','CBA'][e],firstLaterHour=60*Math.ceil((t+3*firstDuration)/60),rows=[];for(let j=0;j<n;j++)rows.push({number:j+1,receipt:j<5?t+j*u:firstLaterHour+(j-5)*u,service:cycle[j%3],duration:j<5?firstDuration:u});return queue(rows,3);}

export function bookFor(rows:Visit[]):Book{const visits:Sheet=new Map(),analysis:Sheet=new Map();for(const [i,r]of rows.entries())for(const [j,c]of [r.number,r.receipt,r.service,r.window,r.start,r.duration,r.end,r.wait,r.waiting,r.rank].entries())visits.set('ABCDEFGHIJ'[j]+(i+3),c);for(let i=0;i<9;i++){analysis.set('A'+(i+4),600+i*60);analysis.set('B'+(i+4),659+i*60);}for(let i=0;i<3;i++){const name='ABC'[i],rs=rows.filter(r=>r.service===name);analysis.set('F'+(i+4),name);analysis.set('G'+(i+4),rs.length);analysis.set('H'+(i+4),rs.length/rows.length);}for(let i=0;i<5;i++)analysis.set('F'+(i+10),i+1);return{来店状況:visits,分析:analysis};}
/** Execute the actual source-spelled holes in the original control skeleton.
 * Dynamic evaluation is deliberately absent: only the 18 published operations
 * and fixed sheet-relative accesses in this one problem are admitted. */
export function macro(rows:Visit[],windows:number,holes:[string,string,string],program:string[]){assert(program.includes('i: 1, i ≤ B1, 1'));assert(program.includes('i: 2, i ≤ B1, 1'));assert(program.includes('論理積(sw = 0, work_line ≤ 250)'));assert(program.includes('work_line ← work_line + 1'));assert(program.indexOf('work_line ← work_line + 1')<program.indexOf('相対(A2, work_line, 0) = null'));const end:(number|null)[]=Array(9).fill(null);for(let i=1;i<=windows;i++)end[i]=0;const out:{window:number;start:number;end:number}[]=[];let work_line=1,sw=0;while(sw===0&&work_line<=250){let min_no=1,min_time=end[1]!,i=2;const row=rows[work_line-1];if(!row)throw Error('READ_EMPTY');const val=(s:string)=>{if(s==='min_time')return min_time;if(s==='min_no')return min_no;if(s==='i')return i;if(s==='work_line')return work_line;const a=/^end_time\[(i|min_no)\]$/.exec(s);if(a){const x=end[a[1]==='i'?i:min_no];if(typeof x!=='number')throw Error('UNINITIALIZED');return x;}if(s==='相対(A2, work_line, 1)')return row.receipt;if(s==='相対(A2, work_line, 4)')return out[work_line-1]?.start??null;if(s==='相対(A2, work_line, 6)')return out[work_line-1]?.end??null;throw Error(s);};for(;i<=windows;i++){const m=/^(min_time) ([<>]) (.+)$/.exec(holes[0]);assert(m);const other=val(m[3]);if(typeof other!=='number')throw Error('EMPTY');if(m[2]==='<'?min_time<other:min_time>other){min_time=end[i]!;min_no=i;}}const window=val(holes[1]);if(typeof window!=='number'||window<1||window>windows)throw Error('INVALID_WINDOW');const start=Math.max(row.receipt,min_time);out.push({window,start,end:start+row.duration});const g=/^end_time\[(min_no|work_line)\] ← (.+)$/.exec(holes[2]);assert(g);const index=g[1]==='min_no'?min_no:work_line;if(index>8)throw Error('ARRAY_BOUND');end[index]=val(g[2]);work_line++;if(!rows[work_line-1])sw=1;}assert.equal(out.length,rows.length);return out;}
